import React, { createContext, useState, useEffect } from "react";

export const ShopContext = createContext(null);

const ShopContextProvider = (props) => {

  const [all_product, setAll_Product] = useState([]);
  const [cartItems, setCartItems] = useState({});
  const [cartSizes, setCartSizes] = useState({});


  /* =========================
     GET PRODUCTS AND CART
     ========================= */

  useEffect(() => {

    // Get all products
    fetch('http://localhost:4000/allproduct')
      .then((response) => response.json())
      .then((data) => {
        setAll_Product(data);
      })
      .catch((error) => {
        console.error("Error fetching products:", error);
      });


    // Get user's cart
    if (localStorage.getItem('auth-token')) {

      fetch('http://localhost:4000/getcart', {
        method: 'POST',

        headers: {
          Accept: 'application/json',
          'auth-token': `${localStorage.getItem('auth-token')}`,
          'Content-Type': 'application/json',
        },

        body: "",
      })

        .then((response) => response.json())

        .then((data) => {
          setCartItems(data);
        })

        .catch((error) => {
          console.error("Error getting cart:", error);
        });

    }

  }, []);


  /* =========================
     ADD TO CART
     ========================= */

  const addToCart = (itemId, selectedSize) => {

    // Increase quantity
    setCartItems((prev) => ({
      ...prev,
      [itemId]: (prev[itemId] || 0) + 1
    }));


    // Save selected size
    setCartSizes((prev) => ({
      ...prev,
      [itemId]: selectedSize
    }));


    // Save to backend
    if (localStorage.getItem('auth-token')) {

      fetch('http://localhost:4000/addtocart', {

        method: 'POST',

        headers: {
          Accept: 'application/json',
          'auth-token': `${localStorage.getItem('auth-token')}`,
          'Content-Type': 'application/json',
        },

        body: JSON.stringify({
          itemId: itemId
        }),

      })

        .then((response) => response.json())

        .then((data) => {
          console.log(data);
        })

        .catch((error) => {
          console.error("Error adding to cart:", error);
        });

    }

  };


  /* =========================
     REMOVE PRODUCT COMPLETELY
     ========================= */

  const removeFromCart = (itemId) => {

    // Remove product completely from frontend cart
    setCartItems((prev) => {

      const updatedCart = { ...prev };

      delete updatedCart[itemId];

      return updatedCart;

    });


    // Remove size information too
    setCartSizes((prev) => {

      const updatedSizes = { ...prev };

      delete updatedSizes[itemId];

      return updatedSizes;

    });


    // Remove product from backend
    if (localStorage.getItem('auth-token')) {

      fetch('http://localhost:4000/removefromcart', {

        method: 'POST',

        headers: {
          Accept: 'application/json',
          'auth-token': `${localStorage.getItem('auth-token')}`,
          'Content-Type': 'application/json',
        },

        body: JSON.stringify({
          itemId: itemId
        }),

      })

        .then((response) => response.json())

        .then((data) => {
          console.log(data);
        })

        .catch((error) => {
          console.error("Error removing from cart:", error);
        });

    }

  };


  /* =========================
     TOTAL CART AMOUNT
     ========================= */

  const getTotalCartAmount = () => {

    let totalAmount = 0;

    for (const item in cartItems) {

      if (cartItems[item] > 0) {

        const itemInfo = all_product.find(
          (product) => product.id === Number(item)
        );

        if (itemInfo) {

          totalAmount +=
            itemInfo.new_price * cartItems[item];

        }

      }

    }

    return totalAmount;

  };


  /* =========================
     CART COUNT
     
     Different products count
     Quantity count නොකරයි.
     ========================= */

  const getTotalCartItems = () => {

    let totalItem = 0;

    for (const item in cartItems) {

      if (cartItems[item] > 0) {

        totalItem += 1;

      }

    }

    return totalItem;

  };


  /* =========================
     CONTEXT VALUE
     ========================= */

  const contextValue = {

    all_product,

    cartItems,

    cartSizes,

    addToCart,

    removeFromCart,

    getTotalCartAmount,

    getTotalCartItems

  };


  return (

    <ShopContext.Provider value={contextValue}>

      {props.children}

    </ShopContext.Provider>

  );

};


export default ShopContextProvider;
